INSERT INTO companies (id, name, description, image) VALUES
	('1', 'PearTech', 'PearTech is a pioneering technology company specializing in the design and manufacture of cutting-edge mobile phones and the development of innovative operating systems. With a commitment to excellence and user-centric design, PearTech aims to deliver seamless, intuitive, and powerful mobile experiences to users worldwide.', 'pear-tech.jpg'),
	('2', 'InnoCore Systems', 'InnoCore Systems is a leading provider of innovative enterprise software solutions designed to streamline business processes and enhance data management. With a focus on delivering cutting-edge technology and exceptional customer service, InnoCore Systems empowers organizations to achieve operational excellence and drive digital transformation.', 'inno-core-system.jpg'),
	('3', 'DroidWave', 'DroidWave is a cutting-edge technology company specializing in the development of advanced robotics and artificial intelligence solutions. Founded with the vision of revolutionizing the way humans interact with technology, DroidWave aims to create seamless, intuitive, and intelligent robotic systems that enhance everyday life and drive innovation across various industries.', 'droid-wave.jpg'),
	('4', 'WorldTrust Financial', 'WorldTrust Financial is a premier independent banking institution dedicated to providing comprehensive financial services on a global scale. With a commitment to innovation, security, and customer satisfaction, WorldTrust Financial offers a wide range of banking solutions designed to meet the diverse needs of individuals, businesses, and institutions worldwide.', 'world-trust-financial.jpg'),
	('5', 'BrokerPro', 'BrokerPro is a leading brokerage firm dedicated to providing comprehensive trading and investment solutions to clients worldwide. With a focus on innovation, reliability, and customer satisfaction, BrokerPro offers a wide range of services designed to meet the diverse needs of individual investors, financial advisors, and institutional clients.', 'broker-pro.jpg'),
	('6', 'TechTalent', 'TechTalent is a premier recruitment agency specializing in the IT industry. Our mission is to connect top-tier tech talent with leading companies, fostering innovation and growth in the digital age. With a deep understanding of the IT landscape and a commitment to excellence, TechTalent Hub is the go-to partner for both job seekers and employers in the tech sector.', 'tech-talent.jpg');